-- 직접 ID를 넣은 테이블의 자동 번호를 이어서 쓸 수 있게 맞춤
DO $$ BEGIN
  PERFORM setval(pg_get_serial_sequence('customers', 'customer_id'), (SELECT max(customer_id) FROM customers));
  PERFORM setval(pg_get_serial_sequence('projects', 'project_id'), (SELECT max(project_id) FROM projects));
  PERFORM setval(pg_get_serial_sequence('users', 'user_id'), (SELECT max(user_id) FROM users));
  PERFORM setval(pg_get_serial_sequence('services', 'service_id'), (SELECT max(service_id) FROM services));
  PERFORM setval(pg_get_serial_sequence('api_keys', 'key_id'), (SELECT max(key_id) FROM api_keys));
  PERFORM setval(pg_get_serial_sequence('models', 'model_id'), (SELECT max(model_id) FROM models));
  PERFORM setval(pg_get_serial_sequence('model_prices', 'price_id'), (SELECT max(price_id) FROM model_prices));
  PERFORM setval(pg_get_serial_sequence('test_scenarios', 'scenario_id'), (SELECT max(scenario_id) FROM test_scenarios));
  PERFORM setval(pg_get_serial_sequence('budgets', 'budget_id'), (SELECT max(budget_id) FROM budgets));
  PERFORM setval(pg_get_serial_sequence('subscription_costs', 'subscription_id'), (SELECT max(subscription_id) FROM subscription_costs));
  PERFORM setval(pg_get_serial_sequence('key_usage_snapshots', 'snapshot_id'), (SELECT max(snapshot_id) FROM key_usage_snapshots));
  PERFORM setval(pg_get_serial_sequence('usage_reconciliations', 'reconciliation_id'), (SELECT max(reconciliation_id) FROM usage_reconciliations));
END $$;
